import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const Wave: React.FC<{ n: number; seed: number; f: number; h: number; color: string; grow: number }> = ({ n, seed, f, h, color, grow }) => (
  <div style={{ display: "flex", alignItems: "center", gap: h * 0.09, flex: 1, height: h }}>
    {Array.from({ length: n }).map((_, i) => {
      const base = 0.25 + 0.75 * Math.abs(Math.sin(i * 1.73 + seed * 2.31));
      const puls = 0.6 + 0.4 * Math.sin(f * 0.24 + i * 0.55 + seed * 1.7);
      const hh = Math.max(2, h * base * puls * grow);
      return <div key={i} style={{ flex: 1, height: hh, borderRadius: 999, background: color, opacity: 0.85 }} />;
    })}
  </div>
);

const ResultsRoll: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const S = Math.min(frame.width / 1080, frame.height / 1920);
  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const heading = String(anim.params?.heading ?? anim.text ?? "Music you can actually use");
  const rawTracks = Array.isArray(anim.params?.tracks) ? (anim.params?.tracks as unknown[]) : [];
  const tracks = (rawTracks.length ? rawTracks : ["TRACK 01", "TRACK 02", "TRACK 03"]).map((t) => String(t));
  const tag = String(anim.params?.tag ?? "FREE TO USE");

  const hs = (heading.length > 34 ? 58 : heading.length > 22 ? 68 : 80) * S;
  const hIn = spring({ frame: f, fps, config: { damping: 200, mass: 0.6 } });

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: "84%", display: "flex", flexDirection: "column", alignItems: "center", gap: 44 * S }}>
        <div
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            textTransform: "uppercase",
            fontSize: hs,
            lineHeight: 1,
            textAlign: "center",
            backgroundImage: headlineGradient(),
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            opacity: hIn,
            transform: `translateY(${(1 - hIn) * 24 * S}px)`,
          }}
        >
          {heading}
        </div>

        <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 24 * S }}>
          {tracks.map((t, i) => {
            const start = 8 + i * 7;
            const rowIn = spring({ frame: f - start, fps, config: { damping: 200, mass: 0.6 } });
            const pill = spring({ frame: f - (start + 22), fps, config: { damping: 12, mass: 0.5 } });
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 22 * S,
                  padding: `${24 * S}px ${28 * S}px`,
                  background: COLORS.vellum,
                  borderRadius: 20 * S,
                  border: `${Math.max(1, 1.2 * S)}px solid rgba(255,255,255,0.10)`,
                  boxShadow: "0 18px 44px rgba(0,0,0,0.38)",
                  opacity: rowIn,
                  transform: `translateX(${(1 - rowIn) * -50 * S}px)`,
                }}
              >
                <div
                  style={{
                    width: 54 * S,
                    height: 54 * S,
                    flex: "0 0 auto",
                    borderRadius: "50%",
                    background: "rgba(255,255,255,0.06)",
                    border: `${Math.max(1, 1.2 * S)}px solid rgba(255,255,255,0.16)`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <div
                    style={{
                      width: 0,
                      height: 0,
                      marginLeft: 4 * S,
                      borderTop: `${10 * S}px solid transparent`,
                      borderBottom: `${10 * S}px solid transparent`,
                      borderLeft: `${16 * S}px solid ${COLORS.tealBright}`,
                    }}
                  />
                </div>

                <div
                  style={{
                    color: muted,
                    fontFamily: FONTS.mono,
                    fontSize: 20 * S,
                    letterSpacing: 0.14 * 20 * S,
                    flex: "0 0 auto",
                  }}
                >
                  {t}
                </div>

                <Wave n={22} seed={i + 1} f={f} h={48 * S} color={COLORS.teal} grow={rowIn} />

                <div
                  style={{
                    flex: "0 0 auto",
                    padding: `${10 * S}px ${18 * S}px`,
                    borderRadius: 999,
                    backgroundImage: headlineGradient(),
                    color: COLORS.ink,
                    fontFamily: FONTS.body,
                    fontWeight: 700,
                    fontSize: 18 * S,
                    letterSpacing: 0.08 * 18 * S,
                    whiteSpace: "nowrap",
                    opacity: Math.max(0, Math.min(1, pill)),
                    transform: `scale(${0.7 + 0.3 * Math.max(0, Math.min(1.1, pill))})`,
                  }}
                >
                  {tag}
                </div>
              </div>
            );
          })}
        </div>

        <div style={{ color: txt, opacity: 0, height: 0, textShadow: ENGRAVE_SHADOW }} />
      </div>
    </AbsoluteFill>
  );
};

export default ResultsRoll;
